import re
from decimal import Decimal, InvalidOperation


_AMOUNT = re.compile(r\"[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?\\Z\")


def parse_amount(text: str) -> int:
    \"\"\"Return cents, rounding exact half cents away from zero.\"\"\"
    if not isinstance(text, str):
        raise ValueError(\"Amount must be a number\")
    value = text.strip().replace(\",\", \"\")
    if value.startswith((\"-"'$", "+$")):
        value = value[0] + value[2:]
    elif value.startswith("$"):
        value = value[1:]
    if not _AMOUNT.fullmatch(value):
        raise ValueError("Amount must be a finite number")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("Amount must be a finite number") from exc
    if not amount.is_finite():
        raise ValueError("Amount must be a finite number")

    # Work from the decimal tuple so precision never depends on the active
    # Decimal context, even for amounts containing many significant digits.
    sign, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    if coefficient == 0:
        return 0
    shift = exponent + 2
    if shift >= 0:
        cents = coefficient * 10 ** shift
    elif -shift > len(digits):
        cents = 0
    else:
        divisor = 10 ** (-shift)
        cents, remainder = divmod(coefficient, divisor)
        if remainder * 2 >= divisor:
            cents += 1
    return -cents if sign else cents
