{"files":[{"path":"ledgerkit/money.py","content":""""Parse human-written money amounts with exact cent rounding."""

from decimal import Decimal, InvalidOperation
import re


def parse_amount(text: str) -> int:
    """Return cents, rounding halfway values away from zero.

    Accept a dollar sign before the number or after its leading sign,
    and ignore surrounding whitespace and thousands commas.
    """
    normalized = text.strip().replace(",", "")
    if normalized.startswith("$"):
        normalized = normalized[1:]
    elif normalized[:2] in ("-$", "+$"):
        normalized = normalized[0] + normalized[2:]

    if not re.fullmatch(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?", normalized):
        raise ValueError("Invalid money amount")
    try:
        amount = Decimal(normalized)
    except InvalidOperation as exc:
        raise ValueError("Invalid money amount") from exc
    if not amount.is_finite():
        raise ValueError("Money amount must be finite")

    # Work directly with decimal digits so the active Decimal precision
    # cannot change either the amount or its rounding.
    sign, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    if coefficient == 0:
        return 0
    cent_exponent = exponent + 2
    if cent_exponent >= 0:
        cents = coefficient * 10**cent_exponent
    elif -cent_exponent > len(digits):
        cents = 0
    else:
        divisor = 10**(-cent_exponent)
        cents, remainder = divmod(coefficient, divisor)
        if remainder * 2 >= divisor:
            cents += 1
    return -cents if sign else cents
"}]}

