from dataclasses import dataclass


@dataclass(frozen=True)
class Item:
    sku: str
    qty: int
    reorder_at: int


def validate_item(item: Item) -> Item:
    """Return the same item if valid, otherwise raise ValueError."""
    if not item.sku or item.sku != item.sku.strip():
        raise ValueError("sku must be nonempty and have no surrounding whitespace")
    if item.qty < 0:
        raise ValueError("qty must be nonnegative")
    if item.reorder_at < 0:
        raise ValueError("reorder_at must be nonnegative")
    return item
