from stockplan.contract import validate_item


def needs_reorder(items) -> list[str]:
    """Return sorted SKUs for validated items at or below their threshold."""
    due = []
    for item in items:
        validate_item(item)
        if item.qty <= item.reorder_at:
            due.append(item.sku)
    return sorted(due)
